class LinkedScrollables extends StatefulWidget {
  @override
  _LinkedScrollablesState createState() => _LinkedScrollablesState();
}

class _LinkedScrollablesState extends State<LinkedScrollables> {
  final LinkedScrollControllerGroup _controllers = LinkedScrollControllerGroup();
  late final ScrollController _letters;
  late final ScrollController _numbers;

  @override
  void initState() {
    super.initState();
    _letters = _controllers.addAndGet();
    _numbers = _controllers.addAndGet();
  }

  @override
  void dispose() {
    _letters.dispose();
    _numbers.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Row(
      children: [
        Expanded(
          child: ListView(controller: _letters, children: const [
            _Tile('Hello A'),
            _Tile('Hello B'),
            _Tile('Hello C'),
            _Tile('Hello D'),
            _Tile('Hello E'),
          ]),
        ),
        Expanded(
          child: ListView(controller: _numbers, children: const [
            _Tile('Hello 1'),
            _Tile('Hello 2'),
            _Tile('Hello 3'),
            _Tile('Hello 4'),
            _Tile('Hello 5'),
          ]),
        ),
      ],
    );
  }
}

class _Tile extends StatelessWidget {
  final String caption;
  const _Tile(this.caption);
  @override
  Widget build(BuildContext context) => Container(
    margin: const EdgeInsets.all(8.0),
    padding: const EdgeInsets.all(8.0),
    height: 250.0,
    child: Center(child: Text(caption)),
  );
}
